import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();

  // Colors from specification
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Dimensions based on atlas region: 512x320 (aspect ratio 1.6)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Setup basic material with structural Node-based shader
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.98
  });

  // Base procedural coloring: Vertical gradient with deep luxury watch aesthetics
  const uvNode = uv();
  const topColor = color(colors.ink);
  const bottomColor = color(colors.surface);

  // Create beautiful engineered accent border on the left edge (signal red)
  const leftEdge = uvNode.x.step(0.015);
  const baseGradient = mix(bottomColor, topColor, uvNode.y);
  const colorWithAccent = mix(color(colors.accent), baseGradient, leftEdge);

  material.colorNode = colorWithAccent;

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Asynchronously load texture map image with fallback
  const imageUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = ctx.THREE.SRGBColorSpace;

    // Mix loaded ceramic grain texture with our luxury colors
    const texNode = texture(tex, uvNode);
    material.colorNode = mix(
      colorWithAccent,
      texNode.rgb,
      uniform(0.18) // Subtle 18% texture blending for high-end feel
    );
    material.needsUpdate = true;
  });

  // Sophisticated subtle contact shadow
  const shadowGeo = new PlaneGeometry(width * 1.2, 0.15);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.35,
    color: 0x000000
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -(height / 2) - 0.05, -0.02);
  shadowMesh.rotation.x = -Math.PI * 0.4;
  group.add(shadowMesh);

  // Subtle natural billboarding/floating behavior
  const clock = new ctx.THREE.Clock();
  let animationFrameId;

  function animate() {
    animationFrameId = requestAnimationFrame(animate);
    const time = clock.getElapsedTime();
    // Gentle premium floating motion
    mesh.position.y = Math.sin(time * 1.5) * 0.02;
    mesh.rotation.y = Math.cos(time * 0.8) * 0.015;
  }
  animate();

  // Entrance animation: GSAP scale-up and rise-in
  const tl = gsap.timeline();
  group.position.y += 0.25;
  group.scale.set(0.9, 0.9, 0.9);

  tl.to(group.position, {
    y: '-=0.25',
    duration: 0.8,
    ease: 'power3.out'
  });
  tl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.8,
    ease: 'power4.out'
  }, '<');

  // Clean up all hooks and animations
  group.userData = {
    cleanup() {
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
      }
      tl.kill();
      geometry.dispose();
      material.dispose();
      shadowGeo.dispose();
      shadowMat.dispose();
    }
  };

  return group;
}
